/** The chart case's five genomes, each given by one letter's share (G and C shares from the GC-content
 * article, maize from Chargaff's table). Its bars are the G share pairing gives, never typed. */
type Letter = 'A' | 'T' | 'C' | 'G';
const GENOMES: { id: string; label: string; letter: Letter; percent: number }[] = [
  { id: 'plasmodium', label: 'Plasmodium falciparum', letter: 'A', percent: 40 },
  { id: 'streptomyces', label: 'Streptomyces coelicolor', letter: 'C', percent: 36 },
  { id: 'yeast', label: 'Yeast', letter: 'A', percent: 31 },
  { id: 'cress', label: 'Thale cress', letter: 'T', percent: 32 },
  { id: 'maize', label: 'Maize', letter: 'C', percent: 23 },
];
/** C faces G, so a C share is the G share; A and T leave the rest for G and C to halve. */
const gShare = (letter: Letter, percent: number) => letter === 'G' || letter === 'C' ? percent : (100 - 2 * percent) / 2;

